# İzmir için üç mevsim. Her ay tam olarak bir mevsime aittir.
SEASONS = [
    ("Kış", "Aralık–Mart: ısıtma yükü yüksek.", [12, 1, 2, 3]),
    ("Geçiş", "Nisan–Mayıs ve Ekim–Kasım: ılıman aylar.", [4, 5, 10, 11]),
    ("Yaz", "Haziran–Eylül: klima yükü yüksek.", [6, 7, 8, 9]),
]
# ornek_gider_yukle komutunun mevsim kayıtlarına yazdığı açıklamanın başı.
LABEL_TO_SEASON = {"Kış dönemi": "Kış", "Geçiş dönemi": "Geçiş", "Yaz dönemi": "Yaz"}


def seasons_and_cleanup(apps, schema_editor):
    Season = apps.get_model("dashboard", "Season")
    SeasonMonth = apps.get_model("dashboard", "SeasonMonth")
    Expense = apps.get_model("dashboard", "MonthlyHotelExpense")
    for name, notes, months in SEASONS:
        season, _ = Season.objects.get_or_create(name=name, defaults={"notes": notes})
        for month in months:
            SeasonMonth.objects.get_or_create(month=month, defaults={"season": season})
    by_name = {season.name: season for season in Season.objects.all()}

    # 1) Mevsim kayıtlarına mevsimlerini yaz (açıklamadaki dönem adından).
    for expense in Expense.objects.filter(season__isnull=True):
        for label, season_name in LABEL_TO_SEASON.items():
            if (expense.description or "").startswith(label):
                expense.season = by_name[season_name]
                expense.save(update_fields=["season"])
                break

    # 2) Tekrar eden mevsim kayıtlarını sil: aynı kalem + aynı mevsim + aynı tutarlar ise yalnızca en erken kayıt
    #    kalır (Ekim'deki geçiş kaydı Nisan'dakinin, Aralık'taki kış kaydı Ocak'takinin aynısıdır).
    groups = {}
    for expense in Expense.objects.filter(season__isnull=False).order_by("expense_month", "id"):
        groups.setdefault((expense.category_id, expense.season_id), []).append(expense)
    for records in groups.values():
        first = records[0]
        for later in records[1:]:
            if later.amount == first.amount and later.variable_rate == first.variable_rate:
                if "elle girilen" in (later.description or ""):
                    first.description = later.description      # kullanıcının girdiği temel değer notu korunur
                    first.save(update_fields=["description"])
                later.delete()

    # 3) Mevsim kaydı, mevsimin o yıldaki İLK ayından başlamalı (Geçiş -> Nisan, Yaz -> Haziran, Kış -> Ocak);
    #    yoksa mevsimin daha önceki ayları (ör. Nisan-Mayıs) o kalemsiz kalır.
    first_month = {season.id: min(SeasonMonth.objects.filter(season=season).values_list("month", flat=True))
                   for season in Season.objects.all()}
    for expense in Expense.objects.filter(season__isnull=False).order_by("expense_month"):
        target = expense.expense_month.replace(month=first_month[expense.season_id], day=1)
        if target < expense.expense_month and not Expense.objects.filter(
                category_id=expense.category_id, expense_month__lte=target, season_id=expense.season_id).exists() \
                and not Expense.objects.filter(category_id=expense.category_id, expense_month=target).exists():
            expense.expense_month = target
            expense.save(update_fields=["expense_month"])


